begin read only;
set local statement_timeout='20s';
select jsonb_build_object(
 'checked_at',clock_timestamp(),
 'counts',(select jsonb_object_agg(t,n) from (select 'application_events' t,count(*) n from public."application_events" union all select 'asset_profiles' t,count(*) n from public."asset_profiles" union all select 'assets' t,count(*) n from public."assets" union all select 'audit_events' t,count(*) n from public."audit_events" union all select 'client_documents' t,count(*) n from public."client_documents" union all select 'client_notes' t,count(*) n from public."client_notes" union all select 'clients' t,count(*) n from public."clients" union all select 'commitments' t,count(*) n from public."commitments" union all select 'compliance_alerts' t,count(*) n from public."compliance_alerts" union all select 'conversion_requests' t,count(*) n from public."conversion_requests" union all select 'custody_vaults' t,count(*) n from public."custody_vaults" union all select 'custom_inquiries' t,count(*) n from public."custom_inquiries" union all select 'delivery_requests' t,count(*) n from public."delivery_requests" union all select 'documents' t,count(*) n from public."documents" union all select 'fee_config' t,count(*) n from public."fee_config" union all select 'fee_waivers' t,count(*) n from public."fee_waivers" union all select 'indexer_events' t,count(*) n from public."indexer_events" union all select 'integrations' t,count(*) n from public."integrations" union all select 'issuer_profiles' t,count(*) n from public."issuer_profiles" union all select 'issuers' t,count(*) n from public."issuers" union all select 'jurisdictions' t,count(*) n from public."jurisdictions" union all select 'kyc_entries' t,count(*) n from public."kyc_entries" union all select 'kyc_registries' t,count(*) n from public."kyc_registries" union all select 'kyc_requirements' t,count(*) n from public."kyc_requirements" union all select 'launch_applications' t,count(*) n from public."launch_applications" union all select 'launch_listings' t,count(*) n from public."launch_listings" union all select 'launch_updates' t,count(*) n from public."launch_updates" union all select 'milestone_claims' t,count(*) n from public."milestone_claims" union all select 'milestones' t,count(*) n from public."milestones" union all select 'notifications' t,count(*) n from public."notifications" union all select 'offers' t,count(*) n from public."offers" union all select 'otc_requests' t,count(*) n from public."otc_requests" union all select 'passport_requests' t,count(*) n from public."passport_requests" union all select 'payout_recipients' t,count(*) n from public."payout_recipients" union all select 'payout_schedules' t,count(*) n from public."payout_schedules" union all select 'payouts' t,count(*) n from public."payouts" union all select 'platforms' t,count(*) n from public."platforms" union all select 'proposals' t,count(*) n from public."proposals" union all select 'resell_listings' t,count(*) n from public."resell_listings" union all select 'rights_issuances' t,count(*) n from public."rights_issuances" union all select 'sales' t,count(*) n from public."sales" union all select 'share_classes' t,count(*) n from public."share_classes" union all select 'spv_issuances' t,count(*) n from public."spv_issuances" union all select 'spvs' t,count(*) n from public."spvs" union all select 'tos_acceptances' t,count(*) n from public."tos_acceptances" union all select 'vesting_beneficiaries' t,count(*) n from public."vesting_beneficiaries" union all select 'vesting_claims' t,count(*) n from public."vesting_claims" union all select 'vesting_milestones' t,count(*) n from public."vesting_milestones" union all select 'vesting_schedules' t,count(*) n from public."vesting_schedules" union all select 'vesting_series' t,count(*) n from public."vesting_series" union all select 'vesting_series_events' t,count(*) n from public."vesting_series_events" union all select 'vote_records' t,count(*) n from public."vote_records") x),
 'blockers',jsonb_build_object(
 'duplicate_client_wallet_groups',(select count(*) from (select wallet from public.clients where wallet is not null group by wallet having count(*)>1) x),
 'duplicate_active_pledge_groups',(select count(*) from (select sale_pubkey,investor_wallet from public.commitments where status in ('pending','confirmed') group by sale_pubkey,investor_wallet having count(*)>1) x),
 'duplicate_custody_vault_groups',(select count(*) from (select network,vault_pda from (select network,vault_pda from public.delivery_requests where vault_pda is not null union all select network,vault_pda from public.conversion_requests where vault_pda is not null) v group by network,vault_pda having count(*)>1) x),
 'duplicate_vesting_chain_groups',(select count(*) from (select network,series_pda from public.vesting_series where series_pda is not null group by network,series_pda having count(*)>1) x),
 'duplicate_listing_application_groups',(select count(*) from (select application_id from public.launch_listings where application_id is not null group by application_id having count(*)>1) x),
 'missing_listing_applications',(select count(*) from public.launch_listings l left join public.launch_applications a on a.id=l.application_id where l.application_id is not null and a.id is null),
 'mismatched_app_listing_sales',(select count(*) from public.launch_listings l join public.launch_applications a on a.id=l.application_id where a.linked_sale_pubkey is distinct from l.sale_pubkey),
 'linked_app_missing_listing',(select count(*) from public.launch_applications a where a.linked_sale_pubkey is not null and not exists(select 1 from public.launch_listings l where l.application_id=a.id and l.sale_pubkey=a.linked_sale_pubkey)),
 'settled_commitments_without_new_evidence',(select count(*) from public.commitments where status='settled'),
 'legacy_approved_vesting_requests',(select count(*) from public.vesting_series where status='approved'),
 'custody_terminal_rows_without_new_evidence',(select count(*) from (select status from public.delivery_requests union all select status from public.conversion_requests) x where status in ('returned','delivered','converted')),
 'custody_link_without_vault_id',(select count(*) from (select vault_pda,vault_id from public.delivery_requests union all select vault_pda,vault_id from public.conversion_requests) x where vault_pda is not null and vault_id is null),
 'share_class_rows_not_v2',(select count(*) from public.share_classes where account_version is distinct from 2 or layout_version is distinct from 2 or readonly_legacy is distinct from false),
 'legacy_vault_vote_snapshots',(select count(*) from public.payout_snapshots where kind='legacy_vault_vote')
 ),
 'networks',jsonb_build_object('asset_profiles',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."asset_profiles" group by 1) x),'assets',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."assets" group by 1) x),'audit_events',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."audit_events" group by 1) x),'clients',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."clients" group by 1) x),'compliance_alerts',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."compliance_alerts" group by 1) x),'conversion_requests',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."conversion_requests" group by 1) x),'custody_vaults',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."custody_vaults" group by 1) x),'custom_inquiries',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."custom_inquiries" group by 1) x),'delivery_requests',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."delivery_requests" group by 1) x),'fee_config',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."fee_config" group by 1) x),'fee_waivers',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."fee_waivers" group by 1) x),'indexer_events',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."indexer_events" group by 1) x),'issuer_profiles',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."issuer_profiles" group by 1) x),'issuers',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."issuers" group by 1) x),'kyc_entries',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."kyc_entries" group by 1) x),'kyc_registries',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."kyc_registries" group by 1) x),'milestone_claims',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."milestone_claims" group by 1) x),'milestones',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."milestones" group by 1) x),'offers',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."offers" group by 1) x),'otc_requests',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."otc_requests" group by 1) x),'platforms',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."platforms" group by 1) x),'proposals',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."proposals" group by 1) x),'resell_listings',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."resell_listings" group by 1) x),'rights_issuances',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."rights_issuances" group by 1) x),'sales',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."sales" group by 1) x),'share_classes',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."share_classes" group by 1) x),'spvs',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."spvs" group by 1) x),'vesting_series',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."vesting_series" group by 1) x),'vote_records',(select coalesce(jsonb_object_agg(network,n),'{}') from (select case when network in ('devnet','mainnet','testnet','localnet') then network else 'unknown_or_null' end network,count(*) n from public."vote_records" group by 1) x)),
 'indexer', (select jsonb_build_object('latest_event',max(created_at),'decoded',count(*) filter(where decoded),'not_decoded',count(*) filter(where not decoded),'latest_slot',max(slot)) from public.indexer_events),
 'extensions',(select jsonb_agg(jsonb_build_object('name',name,'available',true,'default_version',default_version,'installed_version',installed_version) order by name) from pg_available_extensions where name in ('pg_cron','pg_net','supabase_vault')),
 'cron_jobs_table_exists',to_regclass('cron.job') is not null,
 'net_request_queue_exists',to_regclass('net.http_request_queue') is not null,
 'vault_secrets_table_exists',to_regclass('vault.secrets') is not null,
 'triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',p.proname) order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='public' and not t.tgisinternal)
) preflight;
rollback;
